export type ParsedConfirmResultInstruction<
  TProgram extends string = typeof BRACKET_CHAIN_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    counterparty: TAccountMetas[0];
    tournament: TAccountMetas[1];
    matchAccount: TAccountMetas[2];
    /** Required for non-final matches; pass `None` when finalizing the final. */
    nextMatch?: TAccountMetas[3] | undefined;
    participantA: TAccountMetas[4];
    participantB: TAccountMetas[5];
    protocolConfig: TAccountMetas[6];
    vault: TAccountMetas[7];
    organizerTokenAccount?: TAccountMetas[8] | undefined;
    tokenProgram: TAccountMetas[9];
  };
  data: ConfirmResultInstructionData;
};

export function parseConfirmResultInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedConfirmResultInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === BRACKET_CHAIN_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      counterparty: getNextAccount(),
      tournament: getNextAccount(),
      matchAccount: getNextAccount(),
      nextMatch: getNextOptionalAccount(),
      participantA: getNextAccount(),
      participantB: getNextAccount(),
      protocolConfig: getNextAccount(),
      vault: getNextAccount(),
      organizerTokenAccount: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getConfirmResultInstructionDataDecoder().decode(instruction.data),
  };
}
